    public void handleBidAsk(Client client, Map<String, Object> message)
    {
        //
        //     {
        //         "method": "bbo.update",
        //         "data": {
        //             "market": "BTCUSDT",
        //             "updated_at": 1656660154,
        //             "best_bid_price": "20000",
        //             "best_bid_size": "0.1",
        //             "best_ask_price": "20001",
        //             "best_ask_size": "0.15"
        //         },
        //         "id": null
        //     }
        //
        Map<String, Object> data = (Map<String, Object>) this.safeDict(message, "data", new HashMap<String, Object>() {{}});
        Object parsedTicker = this.parseWsBidAsk((Map<String, Object>) (data));
        Object symbol = ((Map<String, Object>)parsedTicker).get("symbol");
        Helpers.addElementToObject(this.bidsasks, ((String)symbol), parsedTicker);
        String messageHash = ("bidsasks:" + symbol);
        client.resolve(parsedTicker, messageHash);
    }

    public Object parseWsBidAsk(Map<String, Object> ticker, Map<String, Object> market)
    {
        //
        //     {
        //         "market": "BTCUSDT",
        //         "updated_at": 1656660154,
        //         "best_bid_price": "20000",
        //         "best_bid_size": "0.1",
        //         "best_ask_price": "20001",
        //         "best_ask_size": "0.15"
        //     }
        //
        String defaultType = this.safeString(this.options, "defaultType");
        String marketId = this.safeString(ticker, "market");
        market = (Map<String, Object>) (this.safeMarket(marketId, market, null, defaultType));
        Long timestamp = this.safeInteger(ticker, "updated_at");
        final Map<String, Object> finalMarket = market;
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", Coinex.this.safeSymbol(marketId, finalMarket, null, defaultType) );
            put( "timestamp", timestamp );
            put( "datetime", Coinex.this.iso8601(timestamp) );
            put( "ask", Coinex.this.safeNumber(ticker, "best_ask_price") );
            put( "askVolume", Coinex.this.safeNumber(ticker, "best_ask_size") );
            put( "bid", Coinex.this.safeNumber(ticker, "best_bid_price") );
            put( "bidVolume", Coinex.this.safeNumber(ticker, "best_bid_size") );
            put( "info", ticker );
        }}, market);
    }
    public Object parseWsBidAsk(Map<String, Object> ticker, Object... optionalArgs)
    {
        return this.parseWsBidAsk(ticker, Helpers.getArgMap(optionalArgs, 0, null));
    }

    public void handleMessage(Client client, Object message)
    {
        String method = this.safeString(message, "method");
        String error = this.safeString(message, "message");
        if (!java.util.Objects.equals(error, null))
        {
            this.handleErrors(1, "", client.url, ((String)method), new HashMap<String, Object>() {{}}, this.json(error), message, new HashMap<String, Object>() {{}}, new HashMap<String, Object>() {{}});
        }
        Map<String, Object> handlers = new HashMap<String, Object>() {{
            put( "state.update", "handleTicker");
            put( "balance.update", "handleBalance");
            put( "deals.update", "handleTrades");
            put( "user_deals.update", "handleMyTrades");
            put( "depth.update", "handleOrderBook");
            put( "order.update", "handleOrders");
            put( "stop.update", "handleOrders");
            put( "bbo.update", "handleBidAsk");
        }};
        Object handler = this.safeValue(handlers, method);
        if (!java.util.Objects.equals(handler, null))
        {
            Helpers.callDynamically(this, handler, new Object[] {client, message});
            return;
        }
        this.handleSubscriptionStatus(client, (Map<String, Object>) (message));
    }

    public Object handleErrors(Object code, Object reason, Object url, Object method, Object headers, Object body, Object response, Object requestHeaders, Object requestBody)
    {
        if (java.util.Objects.equals(response, null))
        {
            return null;
        }
        //
        //     { "id": 1, "code": 20001, "message": "invalid argument" }
        //     { "id": 2, "code": 21001, "message": "require auth" }
        //     { "id": 1, "code": 21002, "message": "Signature Incorrect" }
        //
        String message = this.safeStringLower(response, "message");
        Boolean isErrorMessage = (!java.util.Objects.equals(message, null)) && (!java.util.Objects.equals(message, "ok"));
        String errorCode = this.safeString(response, "code");
        Boolean isErrorCode = (!java.util.Objects.equals(errorCode, null)) && (!java.util.Objects.equals(errorCode, "0"));
        if (Boolean.TRUE.equals(isErrorCode) || Boolean.TRUE.equals(isErrorMessage))
        {
            String feedback = ((this.id + " ") + body);
            this.throwExactlyMatchedException(((Map<String, Object>)this.exceptions).get("exact"), errorCode, feedback);
            this.throwBroadlyMatchedException(((Map<String, Object>)this.exceptions).get("broad"), message, feedback);
            throw new ExchangeError(feedback) ;
        }
        return null;
    }

    public void handleAuthenticationMessage(Client client, Map<String, Object> message)
    {
        //
        // success
        //
        //     {
        //         "id": 1,
        //         "code": 0,
        //         "message": "OK"
        //     }
        //
        // fail
        //
        //     {
        //         "id": 1,
        //         "code": 21002,
        //         "message": ""
        //     }
        //
        String status = this.safeStringLower(message, "message");
        String errorCode = this.safeString(message, "code");
        String messageHash = "authenticated";
        if ((java.util.Objects.equals(status, "ok")) || (java.util.Objects.equals(errorCode, "0")))
        {
            io.github.ccxt.ws.Future future = (io.github.ccxt.ws.Future)this.safeValue(client.futures, messageHash);
            ((io.github.ccxt.ws.Future)future).resolve(true);
        } else
        {
            var error = new AuthenticationError(this.json(message));
            client.reject(error, messageHash);
            if (((Map<?, ?>)client.subscriptions).containsKey(messageHash))
            {
                ((Map<String,Object>)client.subscriptions).remove(messageHash);
            }
        }
    }

    public void handleSubscriptionStatus(Client client, Map<String, Object> message)
    {
        Object id = this.safeInteger(message, "id");
        Map<String, Object> subscription = (Map<String, Object>) this.safeDict(client.subscriptions, id);
        if (!java.util.Objects.equals(subscription, null))
        {
            String futureIndex = this.safeString(subscription, "future");
            io.github.ccxt.ws.Future future = (io.github.ccxt.ws.Future)this.safeValue(client.futures, futureIndex);
            if (!java.util.Objects.equals(future, null))
            {
                ((io.github.ccxt.ws.Future)future).resolve(true);
            }
            ((Map<String,Object>)client.subscriptions).remove((String)id);
        }
    }

    public CompletableFuture<Object> authenticate(Object type)
    {

        return BaseExchange.supplyAsync(() -> {

            String url = (String) Helpers.GetValue(((Map<String, Object>)((Map<String, Object>)this.urls).get("api")).get("ws"), type);
            Client client = this.client(url);
            Long time = this.milliseconds();
            String timestamp = String.valueOf(time);
            String messageHash = "authenticated";
            io.github.ccxt.ws.Future future = client.reusableFuture(messageHash);
            Object authenticated = this.safeValue(client.subscriptions, messageHash);
            if (!java.util.Objects.equals(authenticated, null))
            {
                return ((io.github.ccxt.ws.Future)future).getFuture().join();
            }
            Long requestId = this.requestId();
            Map<String, Object> subscribe = new HashMap<String, Object>() {{
                put( "id", requestId );
                put( "future", messageHash );
            }};
            String hmac = (String) this.hmac(this.encode(timestamp), this.encode(this.secret), sha256(), "hex");
            Map<String, Object> request = new HashMap<String, Object>() {{
                put( "id", requestId );
                put( "method", "server.sign" );
                put( "params", new HashMap<String, Object>() {{
                    put( "access_id", Coinex.this.apiKey );
                    put( "signed_str", hmac.toLowerCase() );
                    put( "timestamp", time );
                }} );
            }};
            this.watch(url, messageHash, request, requestId, subscribe);
            ((Map)client.subscriptions).put((String)messageHash, true);
            return ((io.github.ccxt.ws.Future)future).getFuture().join();
        });

    }
